-//! Simply starts and runs testnet for a while.
-use crate::node::{Node, create_nodes, sample_two_nodes};
-use crate::utils::test_helpers::{heavy_test, wait};
-use near_async::time::Clock;
-use near_o11y::testonly::init_integration_logger;
-use near_primitives::transaction::SignedTransaction;
-use std::time::Duration;
-
-fn run_multiple_nodes(num_nodes: usize, num_trials: usize, test_prefix: &str) {
-    init_integration_logger();
-
-    let nodes = create_nodes(num_nodes, test_prefix);
-    let nodes: Vec<_> = nodes.into_iter().map(|cfg| <dyn Node>::new_sharable(cfg)).collect();
-    let account_names: Vec<_> =
-        nodes.iter().map(|node| node.read().account_id().unwrap()).collect();
-
-    for i in 0..num_nodes {
-        nodes[i].write().start();
-    }
-
-    // waiting for nodes to be synced
-    let started = Clock::real().now();
-    loop {
-        if started.elapsed() > Duration::from_secs(10) {
-            panic!("nodes are not synced in 10s");
-        }
-        let all_synced =
-            nodes.iter().all(|node| node.read().view_account(&account_names[0]).is_ok());
-        if all_synced {
-            break;
-        }
-        std::thread::sleep(Duration::from_millis(100));
-    }
-
-    // Execute N trials. In each trial we submit a transaction to a random node i, that sends
-    // 1 token to a random node j. We send transaction to node Then we wait for the balance change to propagate by checking
-    // the balance of j on node k.
-    let trial_duration = 60_000;
-    let amount_to_send = 100 * 10u128.pow(24);
-    for trial in 0..num_trials {
-        println!("TRIAL #{}", trial);
-        let (i, j) = sample_two_nodes(num_nodes);
-        let (k, r) = sample_two_nodes(num_nodes);
-        let nonce_i = nodes[i].read().get_access_key_nonce_for_signer(&account_names[i]).unwrap();
-        let account_j = nodes[k].read().view_account(&account_names[j]).unwrap();
-        let transaction = SignedTransaction::send_money(
-            nonce_i + 1,
-            account_names[i].clone(),
-            account_names[j].clone(),
-            &*nodes[i].read().signer(),
-            amount_to_send,
-            nodes[k].read().user().get_best_block_hash().unwrap(),
-        );
-        nodes[k].read().add_transaction(transaction).unwrap();
-
-        wait(
-            || {
-                account_j.amount
-                    < nodes[r].read().view_balance(&account_names[j]).unwrap()
-                        - amount_to_send * 9 / 10
-            },
-            100,
-            trial_duration,
-        );
-    }
-}
-
-#[test]
-fn ultra_slow_test_2_10_multiple_nodes() {
-    heavy_test(|| run_multiple_nodes(2, 10, "2_10"));
-}
-
-#[test]
-fn ultra_slow_test_4_10_multiple_nodes() {
-    heavy_test(|| run_multiple_nodes(4, 10, "4_10"));
-}
-
-#[test]
-fn ultra_slow_test_7_10_multiple_nodes() {
-    heavy_test(|| run_multiple_nodes(7, 10, "7_10"));
-}

--- integration-tests/src/tests/other_tests/test_tps_regression.rs ---
@@ -1,164 +0,0 @@
-//! Measures the input and the output transactions-per-seconds, compares it with the expected tps,
-//! and verifies that the output tps is not much different from the input tps (makes sure there is
-//! no choking on transactions). The input tps -- is how fast the nodes can be accepting
-//! transactions. The output tps -- is how fast the nodes propagate transactions into the blocks.
-use crate::node::{Node, create_nodes, sample_queryable_node, sample_two_nodes};
-use crate::utils::test_helpers::heavy_test;
-use near_primitives::transaction::SignedTransaction;
-use parking_lot::RwLock;
-use std::io::Write;
-use std::io::stdout;
-use std::sync::Arc;
-use std::thread;
-use std::time::{Duration, Instant};
-
-/// Creates and sends a random transaction.
-/// Args:
-/// `nodes`: node to submit to;
-/// `nonces`: tracker of the nonces for the corresponding accounts.
-/// `submitted_transactions`: (number of transactions, when these transactions were submitted).
-fn send_transaction(
-    nodes: Vec<Arc<RwLock<dyn Node>>>,
-    nonces: Arc<RwLock<Vec<u64>>>,
-    submitted_transactions: Arc<RwLock<Vec<u64>>>,
-) {
-    let (money_sender, money_receiver) = sample_two_nodes(nodes.len());
-    let tx_receiver = money_sender;
-    // Update nonces.
-    let mut nonces = nonces.write();
-    nonces[money_sender] += 1;
-    let nonce = nonces[money_sender];
-
-    let sender_acc = nodes[money_sender].read().account_id().unwrap();
-    let receiver_acc = nodes[money_receiver].read().account_id().unwrap();
-    if let Some(block_hash) = nodes[tx_receiver].read().user().get_best_block_hash() {
-        let transaction = SignedTransaction::send_money(
-            nonce,
-            sender_acc,
-            receiver_acc,
-            &*nodes[money_sender].read().signer(),
-            1,
-            block_hash,
-        );
-        nodes[tx_receiver].read().add_transaction(transaction).unwrap();
-        submitted_transactions.write().push(1);
-    }
-}
-
-/// Creates a network of nodes and submits a large number of transactions to them.
-/// Args:
-/// * `num_nodes`: number of nodes to create;
-/// * `tps`: transactions-per-second rate with which we submit transactions at even intervals;
-/// * `target_tps`: the target output transactions-per-seconds of the network;
-/// * `timeout`: how long this test should run.
-fn run_multiple_nodes(
-    num_nodes: usize,
-    tps: usize,
-    target_tps: usize,
-    timeout: Duration,
-    test_prefix: &str,
-) {
-    let nodes = create_nodes(num_nodes, test_prefix);
-
-    let nodes: Vec<Arc<RwLock<dyn Node>>> =
-        nodes.into_iter().map(|cfg| <dyn Node>::new_sharable(cfg)).collect();
-    for i in 0..num_nodes {
-        nodes[i].write().start();
-    }
-
-    // Collection that stores #num of transactions -> when these transaction were submitted.
-    let submitted_transactions = Arc::new(RwLock::new(vec![]));
-
-    // Create thread that submits transactions with high tps.
-    let transaction_handler = {
-        // Delay between transactions.
-        let tx_delay =
-            Duration::from_nanos((Duration::from_secs(1).as_nanos() as u64) / (tps as u64));
-        let timeout = Instant::now() + timeout;
-        let nodes = nodes.to_vec();
-        let submitted_transactions = submitted_transactions.clone();
-
-        thread::spawn(move || {
-            let nonces = vec![0u64; nodes.len()];
-            let nonces = Arc::new(RwLock::new(nonces));
-            while Instant::now() < timeout {
-                {
-                    let nodes = nodes.to_vec();
-                    let nonces = nonces.clone();
-                    let submitted_transactions = submitted_transactions.clone();
-                    thread::spawn(move || send_transaction(nodes, nonces, submitted_transactions));
-                }
-                thread::sleep(tx_delay);
-            }
-        })
-    };
-
-    // Delay between checking the nodes.
-    let check_delay = Duration::from_millis(100);
-    // Collection that stores #num of transactions in a block -> when this block was observed.
-    let observed_transactions = Arc::new(RwLock::new(vec![]));
-
-    // Create thread that observes new blocks and counts new transactions in them.
-    let observer_handler = {
-        let timeout = Instant::now() + timeout;
-        let observed_transactions = observed_transactions.clone();
-        thread::spawn(move || {
-            let mut prev_ind = 0;
-            while Instant::now() < timeout {
-                // Get random node.
-                let node = &nodes[sample_queryable_node(&nodes)];
-                if let Some(new_ind) = node.read().user().get_best_height() {
-                    if new_ind > prev_ind {
-                        let blocks = ((prev_ind + 1)..=new_ind)
-                            .filter_map(|idx| node.read().user().get_block_by_height(idx))
-                            .collect::<Vec<_>>();
-                        for b in &blocks {
-                            let tx_num = b.chunks.iter().fold(0, |acc, chunk| {
-                                if chunk.height_included == b.header.height {
-                                    let chunk = node
-                                        .read()
-                                        .user()
-                                        .get_chunk_by_height(b.header.height, chunk.shard_id)
-                                        .unwrap();
-                                    acc + chunk.transactions.len()
-                                } else {
-                                    acc
-                                }
-                            });
-                            observed_transactions.write().push(tx_num as u64);
-                        }
-                        prev_ind = new_ind;
-                    }
-                }
-                thread::sleep(check_delay);
-            }
-        })
-    };
-    transaction_handler.join().unwrap();
-    observer_handler.join().unwrap();
-
-    let submitted_txn_num = submitted_transactions.read().iter().sum::<u64>();
-    let observed_txn_num = observed_transactions.read().iter().sum::<u64>();
-
-    let _ = stdout().write(format!("Submitted transactions: {:?}; ", submitted_txn_num).as_bytes());
-    let _ = stdout().write(format!("Observed transactions: {:?}", observed_txn_num).as_bytes());
-    let _ = stdout().flush();
-
-    // Test that the network does not choke. The choke can be observed when the number of submitted
-    // transactions is not approx. the same the number of observed.
-
-    // The difference is within 20%.
-    assert!(
-        (submitted_txn_num as f64 - observed_txn_num as f64).abs()
-            < u64::max(submitted_txn_num, observed_txn_num) as f64 * 0.2
-    );
-
-    // Also verify that the average tps is within 20% of the target.
-    assert!((target_tps as f64) * 0.8 < (observed_txn_num as f64 / timeout.as_secs_f64()));
-}
-
-#[test]
-fn ultra_slow_test_high_load() {
-    // Run 4 nodes with 20 input tps and check the output tps to be 20.
-    heavy_test(|| run_multiple_nodes(4, 20, 20, Duration::from_secs(120), "4_20"));
-}

