+			valueStart := keyEnd + 1
+			for valueStart < partEnd && cc[valueStart] == ' ' {
+				valueStart++
+			}
+			valueEnd := partEnd
+			for valueEnd > valueStart && cc[valueEnd-1] == ' ' {
