+func setResponseDate(date time.Time) fiber.Handler {
+	return func(c fiber.Ctx) error {
+		if err := c.Next(); err != nil {
+			return err
+		}
+		c.Response().Header.Set(fiber.HeaderDate, date.UTC().Format(http.TimeFormat))
+		return nil
+	}
+}
