+
+	resp, err = app.Test(newRequest(authTokenA))
+	require.NoError(t, err)
+	require.Equal(t, cacheHit, resp.Header.Get("X-Cache"))
+	body, err = io.ReadAll(resp.Body)
+	require.NoError(t, err)
+	require.Equal(t, "body-1-Bearer "+authTokenA, string(body))
