@@ -0,0 +1,137 @@
+import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
+import { trackEvent, _resetIdentityCache } from "./observability";
+
+const capture = vi.fn(async () => undefined);
+const shutdown = vi.fn(async () => undefined);
+const PostHogMock = vi.fn(function (_key: string, _cfg: any) {
+  return { capture, shutdown };
+});
+vi.mock("posthog-node", () => ({ PostHog: PostHogMock }));
+
+describe("trackEvent", () => {
+  const originalEnv = { ...process.env };
+  const originalFetch = globalThis.fetch;
+
+  beforeEach(() => {
+    vi.clearAllMocks();
+    _resetIdentityCache();
+    process.env = { ...originalEnv };
+  });
+
+  afterEach(() => {
+    process.env = originalEnv;
+    globalThis.fetch = originalFetch;
+  });
+
+  it("skips when DO_NOT_TRACK is set", () => {
+    process.env.DO_NOT_TRACK = "1";
+    trackEvent("test-key", "https://test.api", "test.event", { foo: "bar" });
+    expect(PostHogMock).not.toHaveBeenCalled();
+  });
+
+  it("captures event with email identity when whoami succeeds", async () => {
+    globalThis.fetch = vi.fn().mockResolvedValue({
+      ok: true,
+      json: async () => ({ email: "user@test.com", id: "123" }),
+    }) as any;
+
+    trackEvent("test-key", "https://test.api", "sdk.localize.start", {
+      method: "localizeText",
+    });
+
+    await new Promise((r) => setTimeout(r, 200));
+
+    expect(capture).toHaveBeenCalledWith(
+      expect.objectContaining({
+        distinctId: "user@test.com",
+        event: "sdk.localize.start",
+        properties: expect.objectContaining({
+          method: "localizeText",
+          distinct_id_source: "email",
+          tracking_version: "1.0",
+          sdk_package: "@lingo.dev/_sdk",
+        }),
+      }),
+    );
+    expect(shutdown).toHaveBeenCalledTimes(1);
+  });
+
+  it("falls back to API key hash when whoami fails", async () => {
+    globalThis.fetch = vi
+      .fn()
+      .mockRejectedValue(new Error("Network error")) as any;
+
+    trackEvent("my-api-key", "https://test.api", "sdk.localize.start", {});
+
+    await new Promise((r) => setTimeout(r, 200));
+
+    expect(capture).toHaveBeenCalledWith(
+      expect.objectContaining({
+        distinctId: expect.stringMatching(/^apikey-[a-f0-9]{16}$/),
+        properties: expect.objectContaining({
+          distinct_id_source: "api_key_hash",
+        }),
+      }),
+    );
+  });
+
+  it("falls back to API key hash when whoami returns no email", async () => {
+    globalThis.fetch = vi.fn().mockResolvedValue({
+      ok: true,
+      json: async () => ({}),
+    }) as any;
+
+    trackEvent("my-api-key", "https://test.api", "sdk.localize.start", {});
+
+    await new Promise((r) => setTimeout(r, 200));
+
+    expect(capture).toHaveBeenCalledWith(
+      expect.objectContaining({
+        distinctId: expect.stringMatching(/^apikey-[a-f0-9]{16}$/),
+        properties: expect.objectContaining({
+          distinct_id_source: "api_key_hash",
+        }),
+      }),
+    );
+  });
+
+  it("caches identity across multiple calls", async () => {
+    const mockFetch = vi.fn().mockResolvedValue({
+      ok: true,
+      json: async () => ({ email: "user@test.com", id: "123" }),
+    });
+    globalThis.fetch = mockFetch as any;
+
+    trackEvent("test-key", "https://test.api", "event1", {});
+    await new Promise((r) => setTimeout(r, 200));
+
+    trackEvent("test-key", "https://test.api", "event2", {});
+    await new Promise((r) => setTimeout(r, 200));
+
+    // whoami fetch should only be called once due to caching
+    const whoamiCalls = mockFetch.mock.calls.filter(
+      (call) => typeof call[0] === "string" && call[0].includes("/whoami"),
+    );
+    expect(whoamiCalls).toHaveLength(1);
+    expect(capture).toHaveBeenCalledTimes(2);
+  });
+
+  it("uses different cache entries for different API keys", async () => {
+    const mockFetch = vi.fn().mockResolvedValue({
+      ok: true,
+      json: async () => ({ email: "user@test.com", id: "123" }),
+    });
+    globalThis.fetch = mockFetch as any;
+
+    trackEvent("key-1", "https://test.api", "event1", {});
+    await new Promise((r) => setTimeout(r, 200));
+
+    trackEvent("key-2", "https://test.api", "event2", {});
+    await new Promise((r) => setTimeout(r, 200));
+
+    const whoamiCalls = mockFetch.mock.calls.filter(
+      (call) => typeof call[0] === "string" && call[0].includes("/whoami"),
+    );
+    expect(whoamiCalls).toHaveLength(2);
+  });
+});

--- packages/sdk/src/utils/observability.ts ---
@@ -0,0 +1,109 @@
+import { createHash } from "crypto";
+import { TRACKING_VERSION, SDK_PACKAGE } from "./tracking-events";
+
+const POSTHOG_API_KEY = "phc_eR0iSoQufBxNY36k0f0T15UvHJdTfHlh8rJcxsfhfXk";
+const POSTHOG_HOST = "https://eu.i.posthog.com";
+
+type IdentityInfo = {
+  distinct_id: string;
+  distinct_id_source: string;
+};
+
+const identityCache = new Map<string, IdentityInfo>();
+
+export function trackEvent(
+  apiKey: string,
+  apiUrl: string,
+  event: string,
+  properties?: Record<string, any>,
+): void {
+  if (process.env.DO_NOT_TRACK === "1") {
+    return;
+  }
+
+  resolveIdentityAndCapture(apiKey, apiUrl, event, properties).catch(
+    (error) => {
+      if (process.env.DEBUG === "true") {
+        console.error("[Tracking] Error:", error);
+      }
+    },
+  );
+}
+
+async function resolveIdentityAndCapture(
+  apiKey: string,
+  apiUrl: string,
+  event: string,
+  properties?: Record<string, any>,
+) {
+  const identityInfo = await getDistinctId(apiKey, apiUrl);
+
+  if (process.env.DEBUG === "true") {
+    console.log(
+      `[Tracking] Event: ${event}, ID: ${identityInfo.distinct_id}, Source: ${identityInfo.distinct_id_source}`,
+    );
+  }
+
+  const { PostHog } = await import("posthog-node");
+  const posthog = new PostHog(POSTHOG_API_KEY, {
+    host: POSTHOG_HOST,
+    flushAt: 1,
+    flushInterval: 0,
+  });
+
+  await posthog.capture({
+    distinctId: identityInfo.distinct_id,
+    event,
+    properties: {
+      ...properties,
+      tracking_version: TRACKING_VERSION,
+      sdk_package: SDK_PACKAGE,
+      distinct_id_source: identityInfo.distinct_id_source,
+    },
+  });
+
+  await posthog.shutdown();
+}
+
+async function getDistinctId(
+  apiKey: string,
+  apiUrl: string,
+): Promise<IdentityInfo> {
+  const cached = identityCache.get(apiKey);
+  if (cached) return cached;
+
+  try {
+    const res = await fetch(`${apiUrl}/whoami`, {
+      method: "POST",
+      headers: {
+        Authorization: `Bearer ${apiKey}`,
+        "Content-Type": "application/json",
+      },
+    });
+    if (res.ok) {
+      const payload = await res.json();
+      if (payload?.email) {
+        const identity: IdentityInfo = {
+          distinct_id: payload.email,
+          distinct_id_source: "email",
+        };
+        identityCache.set(apiKey, identity);
+        return identity;
+      }
+    }
+  } catch {
+    // Fall through to API key hash
+  }
+
+  const hash = createHash("sha256").update(apiKey).digest("hex").slice(0, 16);
+  const identity: IdentityInfo = {
+    distinct_id: `apikey-${hash}`,
+    distinct_id_source: "api_key_hash",
+  };
+  identityCache.set(apiKey, identity);
+  return identity;
+}
+
+export function _resetIdentityCache() {
+  identityCache.clear();
+}

--- packages/sdk/src/utils/tracking-events.spec.ts ---
@@ -0,0 +1,28 @@
+import { describe, it, expect } from "vitest";
+import {
+  TRACKING_EVENTS,
+  TRACKING_VERSION,
+  SDK_PACKAGE,
+} from "./tracking-events";
+
+describe("tracking-events", () => {
+  it("all events have sdk. prefix", () => {
+    Object.values(TRACKING_EVENTS).forEach((event) => {
+      expect(event).toMatch(/^sdk\./);
+    });
+  });
+
+  it("exports expected constants", () => {
+    expect(TRACKING_VERSION).toBe("1.0");
+    expect(SDK_PACKAGE).toBe("@lingo.dev/_sdk");
+  });
+
+  it("has localize and recognize event groups", () => {
+    expect(TRACKING_EVENTS.LOCALIZE_START).toBe("sdk.localize.start");
+    expect(TRACKING_EVENTS.LOCALIZE_SUCCESS).toBe("sdk.localize.success");
+    expect(TRACKING_EVENTS.LOCALIZE_ERROR).toBe("sdk.localize.error");
+    expect(TRACKING_EVENTS.RECOGNIZE_START).toBe("sdk.recognize.start");
+    expect(TRACKING_EVENTS.RECOGNIZE_SUCCESS).toBe("sdk.recognize.success");
+    expect(TRACKING_EVENTS.RECOGNIZE_ERROR).toBe("sdk.recognize.error");
+  });
+});

