--- packages/utility/src/name.ts ---
@@ -0,0 +1,40 @@
+const cleanNamePart = (namePart: string) => {
+    return (
+        namePart
+            ?.trim()
+            ?.replace(/\s+/g, ' ') // Remove extra spaces
+            ?.replace(/[^\w\s-]/g, '') || '' // Remove special characters except hyphen
+    );
+};
+
+// Helper function to extract first and last name
+export const extractNames = (fullName: string) => {
+    if (!fullName) {
+        return { firstName: '', lastName: '' };
+    }
+
+    // Clean the full name first
+    const cleanedName = fullName.trim().replace(/\s+/g, ' ');
+
+    // Handle empty or whitespace-only names
+    if (!cleanedName) {
+        return { firstName: '', lastName: '' };
+    }
+
+    // Split the name into parts
+    const nameParts = cleanedName.split(' ');
+
+    // Handle single word names
+    if (nameParts.length === 1) {
+        return {
+            firstName: cleanNamePart(nameParts[0] ?? ''),
+            lastName: '',
+        };
+    }
+
+    // Extract first name and last name(s)
+    const firstName = cleanNamePart(nameParts[0] ?? '');
+    const lastName = cleanNamePart(nameParts.slice(1).join(' '));
+
+    return { firstName, lastName };
+};

commit_message:
InferenceClient methods have the proper types now (#1410)

# TL;DR

Types of `InferenceClient` methods are now correct 🥳 

```typescript
const client = new InferenceClient();

const output = client.textToImage(
    {
        inputs: "test input",
        parameters: {
            /// Correctly typed! And auto-completion works!
        },
    },
    options
)
```

