--- packages/utility/src/domain.ts ---
@@ -0,0 +1,70 @@
+/**
+ * Domain utility functions
+ */
+
+/**
+ * Verifies domain ownership by checking various conditions
+ * @param requestDomains - Array of domains to verify
+ * @param ownedDomains - Array of domains that are owned
+ * @param hostingDomain - The main hosting domain (optional)
+ * @returns True if all request domains are owned or valid, false otherwise
+ */
+export const verifyDomainOwnership = (
+    requestDomains: string[],
+    ownedDomains: string[],
+    hostingDomain?: string,
+): boolean => {
+    return requestDomains.every((requestDomain) => {
+        // Check if domain is directly owned
+        if (ownedDomains.includes(requestDomain)) {
+            return true;
+        }
+
+        // Check if www version of owned domain
+        const withoutWww = requestDomain.replace(/^www\./, '');
+        if (ownedDomains.includes(withoutWww)) {
+            return true;
+        }
+
+        // Check if subdomain of hosting domain
+        if (hostingDomain && requestDomain.endsWith(`.${hostingDomain}`)) {
+            return true;
+        }
+
+        return false;
+    });
+};
+
+/**
+ * Checks if a domain is a subdomain of a given parent domain
+ * @param domain - The domain to check
+ * @param parentDomain - The parent domain
+ * @returns True if domain is a subdomain of parentDomain
+ */
+export const isSubdomain = (domain: string, parentDomain: string): boolean => {
+    return domain !== parentDomain && domain.endsWith(`.${parentDomain}`);
+};
+
+/**
+ * Extracts the root domain from a full domain (removes subdomains)
+ * @param domain - The domain to extract root from
+ * @returns The root domain
+ */
+export const getRootDomain = (domain: string): string => {
+    const parts = domain.split('.');
+    if (parts.length <= 2) {
+        return domain;
+    }
+    return parts.slice(-2).join('.');
+};
+
+/**
+ * Validates if a string is a valid domain format
+ * @param domain - The domain string to validate
+ * @returns True if the domain format is valid
+ */
+export const isValidDomain = (domain: string): boolean => {
+    const domainRegex =
+        /^(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)*[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/i;
+    return domainRegex.test(domain) && domain.length <= 253;
+};

--- packages/utility/src/file.ts ---
@@ -0,0 +1,109 @@
+/**
+ * Check if a file is binary based on its extension
+ * @param filename - The filename to check
+ * @returns True if the file is binary, false otherwise
+ */
+export const isBinaryFile = (filename: string): boolean => {
+    const binaryExtensions = [
+        '.jpg',
+        '.jpeg',
+        '.png',
+        '.gif',
+        '.bmp',
+        '.svg',
+        '.ico',
+        '.webp',
+        '.pdf',
+        '.zip',
+        '.tar',
+        '.gz',
+        '.rar',
+        '.7z',
+        '.mp3',
+        '.mp4',
+        '.wav',
+        '.avi',
+        '.mov',
+        '.wmv',
+        '.exe',
+        '.bin',
+        '.dll',
+        '.so',
+        '.dylib',
+        '.woff',
+        '.woff2',
+        '.ttf',
+        '.eot',
+        '.otf',
+    ];
+
+    const ext = filename.toLowerCase().substring(filename.lastIndexOf('.'));
+    return binaryExtensions.includes(ext);
+};
+
+/**
+ * File operation interface for abstracted file operations
+ */
+export interface FileOperations {
+    readFile: (filePath: string) => Promise<string | null>;
+    writeFile: (filePath: string, content: string) => Promise<boolean>;
+    fileExists: (filePath: string) => Promise<boolean>;
+    deleteFile: (filePath: string) => Promise<boolean>;
+    copyDir: (source: string, destination: string) => Promise<boolean>;
+    copyFile: (source: string, destination: string) => Promise<boolean>;
+}
+
+/**
+ * Updates .gitignore file to include a target entry
+ * @param target - The entry to add to .gitignore
+ * @param fileOps - File operations interface
+ * @returns True if successfully updated, false otherwise
+ */
+export const updateGitignore = async (
+    target: string,
+    fileOps: FileOperations,
+): Promise<boolean> => {
+    const gitignorePath = '.gitignore';
+
+    try {
+        // Check if .gitignore exists
+        const gitignoreExists = await fileOps.fileExists(gitignorePath);
+
+        if (!gitignoreExists) {
+            // Create .gitignore with the target
+            await fileOps.writeFile(gitignorePath, target + '\n');
+            return true;
+        }
+
+        // Read existing .gitignore content
+        const gitignoreContent = await fileOps.readFile(gitignorePath);
+        if (gitignoreContent === null) {
+            return false;
+        }
+
+        const lines = gitignoreContent.split(/\r?\n/);
+
+        // Look for exact match of target
+        if (!lines.some((line: string) => line.trim() === target)) {
+            // Ensure there's a newline before adding if the file doesn't end with one
+            const separator = gitignoreContent.endsWith('\n') ? '' : '\n';
+            await fileOps.writeFile(gitignorePath, gitignoreContent + `${separator}${target}\n`);
+        }
+
+        return true;
+    } catch (error) {
+        console.error(`Failed to update .gitignore: ${error}`);
+        return false;
+    }
+};
+
+export const getDirName = (filePath: string): string => {
+    const parts = filePath.split('/');
+    if (parts.length <= 1) return '.';
+    return parts.slice(0, -1).join('/') || '.';
+};
+
+export const getBaseName = (filePath: string): string => {
+    const parts = filePath.split('/');
+    return parts[parts.length - 1] || '';
+};

