--- apps/studio/src/lib/user/settings.ts ---
@@ -0,0 +1,56 @@
+import { DefaultSettings, MainChannels } from '@onlook/models/constants';
+import type { ChatSettings, EditorSettings, UserSettings } from '@onlook/models/settings';
+import { makeAutoObservable } from 'mobx';
+import { invokeMainChannel } from '../utils';
+
+export class UserSettingsManager {
+    settings: UserSettings | null = null;
+
+    constructor() {
+        makeAutoObservable(this);
+        this.restoreSettings();
+    }
+
+    async restoreSettings() {
+        this.settings = await invokeMainChannel(MainChannels.GET_USER_SETTINGS);
+    }
+
+    async update(settings: Partial<UserSettings>) {
+        this.settings = { ...this.settings, ...settings };
+        await invokeMainChannel(MainChannels.UPDATE_USER_SETTINGS, settings);
+    }
+
+    async updateChat(newSettings: Partial<ChatSettings>) {
+        const newChatSettings = {
+            ...DefaultSettings.CHAT_SETTINGS,
+            ...this.settings?.chat,
+            ...newSettings,
+        };
+
+        this.settings = {
+            ...this.settings,
+            chat: newChatSettings,
+        };
+
+        await invokeMainChannel(MainChannels.UPDATE_USER_SETTINGS, {
+            chat: newChatSettings,
+        });
+    }
+
+    async updateEditor(newSettings: Partial<EditorSettings>) {
+        const newEditorSettings = {
+            ...DefaultSettings.EDITOR_SETTINGS,
+            ...this.settings?.editor,
+            ...newSettings,
+        };
+
+        this.settings = {
+            ...this.settings,
+            editor: newEditorSettings,
+        };
+
+        await invokeMainChannel(MainChannels.UPDATE_USER_SETTINGS, {
+            editor: newEditorSettings,
+        });
+    }
+}

--- apps/studio/src/lib/user/subscription.ts ---
@@ -0,0 +1,45 @@
+import { MainChannels } from '@onlook/models/constants';
+import { UsagePlanType } from '@onlook/models/usage';
+import { makeAutoObservable } from 'mobx';
+import { invokeMainChannel } from '../utils';
+
+export class SubscriptionManager {
+    plan: UsagePlanType = UsagePlanType.BASIC;
+
+    constructor() {
+        makeAutoObservable(this);
+        this.restoreCachedPlan();
+    }
+
+    private restoreCachedPlan() {
+        const cachedPlan = localStorage.getItem('currentPlan');
+        this.plan = (cachedPlan as UsagePlanType) || UsagePlanType.BASIC;
+    }
+
+    async updatePlan(plan: UsagePlanType) {
+        this.plan = plan;
+        localStorage.setItem('currentPlan', plan);
+        await invokeMainChannel(MainChannels.UPDATE_USER_METADATA, { plan });
+    }
+
+    async getPlanFromServer(): Promise<UsagePlanType> {
+        try {
+            const res:
+                | {
+                      success: boolean;
+                      error?: string;
+                      data?: any;
+                  }
+                | undefined = await invokeMainChannel(MainChannels.CHECK_SUBSCRIPTION);
+            if (!res?.success) {
+                throw new Error(res?.error || 'Error checking premium status');
+            }
+            const newPlan = res.data.name === 'pro' ? UsagePlanType.PRO : UsagePlanType.BASIC;
+            await this.updatePlan(newPlan);
+            return newPlan;
+        } catch (error) {
+            console.error('Error checking premium status:', error);
+            return UsagePlanType.BASIC;
+        }
+    }
+}

