-		if (!session) {
-			return undefined;
-		}
-
-		const logs = await capi.getLogsFromSession(session.id);
-
-		// If session is in progress, try to fetch workflow steps to show setup progress
-		let setupSteps: SessionSetupStep[] | undefined;
