+        )
+
+        if copilot_enabled:
+            LOGGER.debug("GitHub Copilot is enabled")
+
+        if copilot_enabled or language_servers_enabled:
+            LOGGER.debug("Language Servers are enabled")
+            await session_mgr.start_lsp_server()
+
     yield



