-    for receipt in delete_receipts {
-        let new_shard_uid: ShardUId = receipt_to_shard_uid(receipt);
-        if !trie_updates.contains_key(&new_shard_uid) {
-            let err = format!(
-                "Delayed receipt {:?} is in new shard {:?} but state_roots only contains {:?}",
