--- apps/web/client/src/app/_components/top-bar/mega-menu.tsx ---
@@ -0,0 +1,97 @@
+'use client';
+
+import { type NavigationLink } from '@/utils/constants/navigation';
+import { cn } from '@onlook/ui/utils';
+import { useEffect, useRef, useState } from 'react';
+import { Icons } from '@onlook/ui/icons';
+
+interface DropdownMenuProps {
+    label: string;
+    links: NavigationLink[];
+}
+
+export function DropdownMenu({ label, links }: DropdownMenuProps) {
+    const [isOpen, setIsOpen] = useState(false);
+    const menuRef = useRef<HTMLDivElement>(null);
+
+    // Handle click outside to close menu
+    useEffect(() => {
+        const handleClickOutside = (event: MouseEvent) => {
+            if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
+                setIsOpen(false);
+            }
+        };
+
+        if (isOpen) {
+            document.addEventListener('mousedown', handleClickOutside);
+        }
+
+        return () => {
+            document.removeEventListener('mousedown', handleClickOutside);
+        };
+    }, [isOpen]);
+
+    const handleToggle = () => {
+        setIsOpen(!isOpen);
+    };
+
+    return (
+        <div
+            ref={menuRef}
+            className="relative"
+            onMouseEnter={() => {
+                // Only auto-open on hover for desktop
+                if (window.innerWidth >= 768) {
+                    setIsOpen(true);
+                }
+            }}
+            onMouseLeave={() => {
+                // Only auto-close on mouse leave for desktop
+                if (window.innerWidth >= 768) {
+                    setIsOpen(false);
+                }
+            }}
+        >
+            <button
+                onClick={handleToggle}
+                className="text-sm text-foreground-secondary hover:opacity-80 flex items-center gap-1 py-2 px-1 -mx-1 active:opacity-60"
+            >
+                {label}
+                <Icons.ChevronDown
+                    className={cn(
+                        'w-4 h-4 transition-transform',
+                        isOpen && 'rotate-180',
+                    )}
+                />
+            </button>
+
+            {isOpen && (
+                <div className="absolute top-full left-1/2 -translate-x-1/2 pt-2 z-50">
+                    <div className="bg-background-primary border border-foreground-primary/10 rounded-lg shadow-lg p-1 min-w-[200px]">
+                        <ul className="space-y-1">
+                            {links.map((link) => (
+                                <li key={link.href}>
+                                    <a
+                                        href={link.href}
+                                        target={link.external ? '_blank' : undefined}
+                                        rel={link.external ? 'noopener noreferrer' : undefined}
+                                        className="block py-2 px-2 rounded-md hover:bg-foreground-primary/5 active:bg-foreground-primary/10 transition-colors"
+                                        onClick={() => setIsOpen(false)}
+                                    >
+                                        <div className="text-regular text-foreground-primary">
+                                            {link.title}
+                                        </div>
+                                        <div className="text-small text-foreground-tertiary">
+                                            {link.description}
+                                        </div>
+                                    </a>
+                                </li>
+                            ))}
+                        </ul>
+                    </div>
+                </div>
+            )}
+        </div>
+    );
+}
+

--- apps/web/client/src/app/_components/top-bar/mobile-menu.tsx ---
@@ -0,0 +1,127 @@
+'use client';
+
+import { useEffect } from 'react';
+import * as Portal from '@radix-ui/react-portal';
+
+import { Accordion, AccordionContent, AccordionItem, AccordionTrigger } from '@onlook/ui/accordion';
+import { cn } from '@onlook/ui/utils';
+
+import { ExternalRoutes } from '@/utils/constants';
+import { NAVIGATION_CATEGORIES } from '@/utils/constants/navigation';
+
+interface MobileMenuProps {
+    isOpen: boolean;
+    onOpenChange: (open: boolean) => void;
+}
+
+export function MobileMenu({ isOpen, onOpenChange }: MobileMenuProps) {
+    // Handle body scroll lock with class instead of direct style manipulation
+    useEffect(() => {
+        if (isOpen) {
+            document.body.classList.add('overflow-hidden');
+        } else {
+            document.body.classList.remove('overflow-hidden');
+        }
+
+        return () => {
+            document.body.classList.remove('overflow-hidden');
+        };
+    }, [isOpen]);
+
+    return (
+        <>
+            {/* Hamburger button */}
+            <button
+                onClick={() => onOpenChange(!isOpen)}
+                className="text-foreground-secondary flex items-center justify-center p-3 hover:opacity-80 md:hidden"
+                aria-label={isOpen ? 'Close menu' : 'Open menu'}
+            >
+                <svg className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
+                    <path
+                        strokeLinecap="round"
+                        strokeLinejoin="round"
+                        strokeWidth={2}
+                        d="M4 6h16M4 12h16M4 18h16"
+                    />
+                </svg>
+            </button>
+
+            {/* Backdrop - portaled to body */}
+            <Portal.Root>
+                <div
+                    className={cn(
+                        'fixed inset-0 bg-black/40 backdrop-blur-sm transition-all duration-200 md:hidden',
+                        'top-12', // Start below the navbar
+                        isOpen ? 'pointer-events-auto opacity-100' : 'pointer-events-none opacity-0',
+                    )}
+                    onClick={() => onOpenChange(false)}
+                    style={{ zIndex: 40 }}
+                />
+            </Portal.Root>
+
+            {/* Menu panel - portaled to body */}
+            <Portal.Root>
+                <div
+                    className={cn(
+                        'bg-background border-border fixed right-0 left-0 overflow-y-auto border-b shadow-lg transition-all duration-200 md:hidden',
+                        'top-12 max-h-[calc(100vh-3rem)]',
+                        isOpen
+                            ? 'translate-y-0 opacity-100'
+                            : 'pointer-events-none -translate-y-4 opacity-0',
+                    )}
+                    style={{ zIndex: 50 }}
+                >
+                    <Accordion type="single" collapsible className="w-full">
+                        {NAVIGATION_CATEGORIES.map((category) => (
+                            <AccordionItem
+                                key={category.label}
+                                value={category.label}
+                                className="border-border border-b"
+                            >
+                                <AccordionTrigger className="hover:bg-foreground/5 flex w-full items-center justify-between p-4 text-left">
+                                    <span className="text-regular text-foreground-primary">
+                                        {category.label}
+                                    </span>
+                                </AccordionTrigger>
+                                <AccordionContent className="bg-foreground/5">
+                                    {category.links.map((link) => (
+                                        <a
+                                            key={link.href}
+                                            href={link.href}
+                                            onClick={() => onOpenChange(false)}
+                                            className="hover:bg-foreground/10 block p-4 pl-8"
+                                            {...(link.external && {
+                                                target: '_blank',
+                                                rel: 'noopener noreferrer',
+                                            })}
+                                        >
+                                            <div className="text-foreground-primary text-sm font-medium">
+                                                {link.title}
+                                            </div>
+                                            <div className="text-foreground-secondary mt-0.5 text-xs">
+                                                {link.description}
+                                            </div>
+                                        </a>
+                                    ))}
+                                </AccordionContent>
+                            </AccordionItem>
+                        ))}
+                    </Accordion>
+
+                    {/* Bottom CTA */}
+                    <div className="p-4">
+                        <a
+                            href={ExternalRoutes.BOOK_DEMO}
+                            target="_blank"
+                            rel="noopener noreferrer"
+                            onClick={() => onOpenChange(false)}
+                            className="bg-foreground-primary text-background block w-full rounded-lg px-4 py-3 text-center text-sm font-medium transition-opacity hover:opacity-90"
+                        >
+                            Book a Demo
+                        </a>
+                    </div>
+                </div>
+            </Portal.Root>
+        </>
+    );
+}

