+            allowed_domains: args.allowed_domains,
+            blocked_domains: args.blocked_domains,
+        });
+        return res
+    } catch (error) {
+        console.error('Error searching web:', error);
+        return {
+            result: [],
+            error: error instanceof Error ? error.message : 'Unknown error',
+        };
+    }
+}

